import React, { useState, useEffect } from 'react';
import { GameState, Phase } from '../types';

interface TopPanelProps {
  state: GameState;
}

const StatCapsule: React.FC<{
  icon: string;
  value: string | number;
  label: string;
  subValue?: React.ReactNode;
  colorClass?: string;
  warning?: boolean;
  align?: 'left' | 'right';
}> = ({ icon, value, label, subValue, colorClass, warning, align = 'left' }) => {
  return (
    <div className={`
      relative group flex items-center gap-3 px-5 py-3 rounded-2xl
      bg-white/60 backdrop-blur-md border border-white/40 shadow-sm
      transition-all duration-300 hover:bg-white/80 hover:scale-105 hover:shadow-md
      ${warning ? 'animate-pulse bg-red-50/80 border-red-300 ring-2 ring-red-200' : ''}
    `}>
      <div className={`text-2xl filter drop-shadow-sm ${warning ? 'animate-bounce' : ''}`}>{icon}</div>
      <div className={`flex flex-col ${align === 'right' ? 'items-end' : 'items-start'}`}>
        <div className="flex items-baseline gap-1.5">
          <span className={`text-xl font-black leading-none tracking-tight ${colorClass || 'text-slate-800'}`}>
            {value}
          </span>
        </div>
        <div className="flex items-center gap-1.5 mt-0.5">
          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{label}</span>
          {subValue && <span className="text-[10px] font-bold">{subValue}</span>}
        </div>
      </div>
    </div>
  );
};

export const TopPanel: React.FC<TopPanelProps> = ({ state }) => {
  const minutes = Math.floor(state.timer / 60);
  const seconds = state.timer % 60;
  const timeStr = `${minutes}:${seconds.toString().padStart(2, '0')}`;

  const isPowerCritical = state.power > state.powerCapacity;
  const isPollutionCritical = state.pollution > 40;

  // Happiness Emoji Logic
  const getHappinessEmoji = (h: number) => {
    if (h >= 90) return '🤩';
    if (h >= 70) return '😃';
    if (h >= 50) return '🙂';
    if (h >= 30) return '😐';
    if (h >= 10) return '😓';
    return '😭';
  };

  const getPhaseLabel = (p: Phase) => {
    switch (p) {
      case Phase.BUILD: return '建造阶段';
      case Phase.VOTE: return '全民投票';
      case Phase.DISCUSS: return '市民讨论';
      default: return '';
    }
  };

  return (
    <div className="w-full pt-4 px-6 flex items-start justify-between z-50 pointer-events-none absolute top-0 left-0">

      {/* LEFT: Economy & Growth */}
      <div className="flex flex-col gap-3 pointer-events-auto animate-in slide-in-from-left-4 duration-500">
        <StatCapsule 
          icon="💰" 
          value={state.gold.toLocaleString()} 
          label="财政资金"
          colorClass="text-amber-700"
          subValue={
            state.goldDelta !== 0 && (
              <span className={`${state.goldDelta > 0 ? 'text-emerald-600' : 'text-red-500'}`}>
                {state.goldDelta > 0 ? '▲' : '▼'}{Math.abs(state.goldDelta)}/s
              </span>
            )
          }
        />
        <StatCapsule 
          icon="👥" 
          value={`${state.population} / ${state.maxPopulation}`} 
          label="城市人口"
          colorClass="text-blue-700"
        />
      </div>

      {/* CENTER: Game State & Goal */}
      <div className="flex flex-col items-center gap-3 pointer-events-auto animate-in zoom-in duration-500 mt-2">
        {/* Main Happiness Badge */}
        <div className="flex items-center gap-4 px-8 py-2 bg-white/70 backdrop-blur-xl rounded-full border-2 border-white/60 shadow-lg transition-transform hover:scale-105 cursor-help group">
          <span className="text-5xl drop-shadow-md group-hover:animate-bounce">
            {getHappinessEmoji(state.happiness)}
          </span>
          <div className="flex flex-col">
            <span className="text-4xl font-black text-slate-800 leading-none tracking-tighter">
              {state.happiness}<span className="text-lg text-slate-400 ml-1">%</span>
            </span>
            <span className="text-[10px] font-bold text-indigo-500 uppercase tracking-[0.2em]">市民幸福指数</span>
          </div>
        </div>

        {/* Phase Indicator */}
        <div className="flex items-center gap-3 px-6 py-2 bg-slate-800/90 backdrop-blur-md rounded-full text-white shadow-xl border border-slate-700/50">
          <div className={`w-2.5 h-2.5 rounded-full ${state.phase === Phase.BUILD ? 'bg-emerald-400 animate-pulse' : 'bg-yellow-400'}`}></div>
          <span className="text-xs font-bold tracking-widest text-slate-200">
            {getPhaseLabel(state.phase)}
          </span>
          <div className="w-px h-3 bg-white/20 mx-1"></div>
          <span className={`font-mono font-bold text-lg ${state.timer < 10 ? 'text-red-400 animate-pulse' : 'text-emerald-300'}`}>
            {timeStr}
          </span>
        </div>
      </div>

      {/* RIGHT: Sustainability Constraints */}
      <div className="flex flex-col gap-3 pointer-events-auto items-end animate-in slide-in-from-right-4 duration-500">
        <StatCapsule 
          align="right"
          icon="⚡" 
          value={`${state.power} / ${state.powerCapacity}`} 
          label="电力负载"
          colorClass={isPowerCritical ? 'text-red-600' : 'text-slate-700'}
          warning={isPowerCritical}
          subValue={
            <span className={isPowerCritical ? 'text-red-600' : 'text-emerald-600'}>
              {state.powerCapacity - state.power > 0 ? '剩余充足' : '⚠️ 电力过载'}
            </span>
          }
        />
        <StatCapsule 
          align="right"
          icon={isPollutionCritical ? "🌫️" : "🍃"}
          value={`${state.pollution}%`} 
          label="环境污染"
          colorClass={isPollutionCritical ? 'text-orange-700' : 'text-emerald-700'}
          warning={isPollutionCritical}
        />
      </div>

    </div>
  );
};

import React from 'react';
import { Role } from '../types';
import { BUILDINGS, ROLE_INFO } from '../constants';

interface SidebarLeftProps {
  currentRole: Role;
  onSelectBuilding: (id: string) => void;
  selectedId: string | null;
  gold: number;
}

export const SidebarLeft: React.FC<SidebarLeftProps> = ({ currentRole, onSelectBuilding, selectedId, gold }) => {
  const roleInfo = ROLE_INFO[currentRole];
  const buildingsForRole = Object.values(BUILDINGS).filter(b => b.role === currentRole);

  return (
    <div className="w-80 h-full flex flex-col pt-24 pb-6 pl-6 pointer-events-none">
      <div className="flex-1 bg-white/90 backdrop-blur-xl rounded-[32px] border border-white/50 shadow-2xl flex flex-col overflow-hidden pointer-events-auto">

        {/* Header */}
        <div className={`${roleInfo.color} p-6 pb-8 text-white relative overflow-hidden`}>
          <div className="absolute top-0 right-0 p-4 opacity-20 text-6xl transform translate-x-4 -translate-y-2">
            {roleInfo.icon}
          </div>
          <div className="relative z-10">
             <div className="flex items-center gap-3 mb-2">
                <span className="text-3xl bg-white/20 p-2 rounded-2xl shadow-inner">{roleInfo.icon}</span>
                <h2 className="font-black text-2xl tracking-tight">{roleInfo.name}</h2>
             </div>
             <p className="text-xs font-medium opacity-90 leading-relaxed max-w-[90%]">
               职责：{currentRole === Role.ENVIRONMENT ? '规划生态保护区，平衡污染。' : currentRole === Role.PLANNER ? '建设道路与公共设施，保障民生。' : currentRole === Role.ENERGY ? '建设发电设施，确保能源供应。' : '建设商业与办公区，提升经济。'}
             </p>
          </div>
        </div>

        {/* Building List */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 scrollbar-hide">
          {buildingsForRole.map(building => {
            const isSelected = selectedId === building.id;
            const canAfford = gold >= building.cost;

            return (
              <div 
                key={building.id}
                onClick={() => onSelectBuilding(building.id)}
                className={`
                  relative group p-4 rounded-2xl border-2 transition-all duration-200 cursor-pointer
                  ${isSelected 
                    ? `border-${roleInfo.theme}-500 bg-${roleInfo.theme}-50 shadow-md scale-[1.02]` 
                    : 'border-slate-100 hover:border-slate-300 hover:bg-slate-50 bg-white'}
                  ${!canAfford ? 'opacity-60 grayscale' : ''}
                `}
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-3">
                    <span className="text-4xl filter drop-shadow-sm group-hover:scale-110 transition-transform">{building.emoji}</span>
                    <div>
                      <h3 className="font-bold text-slate-800 text-lg leading-tight">{building.name}</h3>
                      <span className={`text-xs font-bold ${canAfford ? 'text-amber-600' : 'text-red-400'}`}>
                        💰 {building.cost}
                      </span>
                    </div>
                  </div>
                  {isSelected && <div className={`w-3 h-3 rounded-full bg-${roleInfo.theme}-500 animate-pulse`}></div>}
                </div>

                {/* Mini Stats Grid */}
                <div className="grid grid-cols-4 gap-1 mt-2">
                  {building.goldEffect !== 0 && (
                    <div className={`col-span-2 px-2 py-1 rounded-lg text-[10px] font-bold ${building.goldEffect > 0 ? 'bg-green-100 text-green-700' : 'bg-red-50 text-red-600'}`}>
                      {building.goldEffect > 0 ? '+' : ''}{building.goldEffect} 金币
                    </div>
                  )}
                  {building.powerEffect !== 0 && (
                    <div className={`col-span-2 px-2 py-1 rounded-lg text-[10px] font-bold ${building.powerEffect > 0 ? 'bg-yellow-100 text-yellow-700' : 'bg-blue-50 text-blue-600'}`}>
                      {building.powerEffect > 0 ? '+' : ''}{building.powerEffect} 电力
                    </div>
                  )}
                  {building.happinessEffect !== 0 && (
                     <div className="col-span-2 px-2 py-1 rounded-lg bg-indigo-50 text-indigo-600 text-[10px] font-bold">
                       +{building.happinessEffect} 幸福
                     </div>
                  )}
                   {building.pollutionEffect !== 0 && (
                     <div className={`col-span-2 px-2 py-1 rounded-lg text-[10px] font-bold ${building.pollutionEffect < 0 ? 'bg-green-100 text-green-700' : 'bg-stone-100 text-stone-600'}`}>
                       {building.pollutionEffect > 0 ? '+' : ''}{building.pollutionEffect} 污染
                     </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Task, Feedback } from '../types';

interface SidebarRightProps {
  tasks: Task[];
  aiAdvice: string;
  feedbacks: Feedback[];
  onRewardClick: () => void;
  onSendFeedback?: (text: string) => void;
}

export const SidebarRight: React.FC<SidebarRightProps> = ({ tasks, aiAdvice, feedbacks, onRewardClick, onSendFeedback }) => {
  const [inputText, setInputText] = useState('');

  const handleSend = () => {
    if (!inputText.trim()) return;
    onSendFeedback?.(inputText);
    setInputText('');
  };

  return (
    <div className="w-80 h-full flex flex-col pt-24 pb-6 pr-6 pointer-events-none gap-4">

      {/* AI Advisor Card */}
      <section className="bg-white/90 backdrop-blur-xl rounded-3xl p-5 border border-blue-100 shadow-xl pointer-events-auto flex flex-col gap-3 relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-20 h-20 bg-blue-400/10 rounded-full -translate-y-1/2 translate-x-1/2"></div>
        <h3 className="text-blue-800 font-black text-sm uppercase tracking-wider flex items-center gap-2 relative z-10">
          <span className="text-lg">🤖</span> AI 智能顾问
        </h3>
        <div className="bg-blue-50/80 p-3 rounded-2xl text-slate-700 text-xs leading-relaxed border border-blue-100">
          "{aiAdvice}"
        </div>
        <button 
          onClick={onRewardClick}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-2.5 rounded-xl transition-all active:scale-95 shadow-lg shadow-blue-200 text-xs flex items-center justify-center gap-2"
        >
          <span>🎁</span> 领取阶段奖励
        </button>
      </section>

      {/* Tasks Card */}
      <section className="flex-[0.8] min-h-0 bg-white/90 backdrop-blur-xl rounded-3xl p-5 border border-yellow-100 shadow-xl pointer-events-auto flex flex-col overflow-hidden">
        <h3 className="text-yellow-800 font-black text-sm uppercase tracking-wider mb-3 flex items-center gap-2">
          <span className="text-lg">📋</span> 城市目标
        </h3>
        <ul className="space-y-2 overflow-y-auto pr-1 flex-1 scrollbar-hide">
          {tasks.map(task => (
            <li key={task.id} className={`
              flex items-start gap-3 p-3 rounded-xl border transition-all
              ${task.completed ? 'bg-gray-50 border-gray-100 opacity-60' : 'bg-white border-yellow-100 shadow-sm'}
            `}>
              <div className={`mt-0.5 w-4 h-4 rounded-full border-2 flex items-center justify-center flex-shrink-0 ${task.completed ? 'bg-green-500 border-green-500' : 'border-gray-300'}`}>
                {task.completed && <span className="text-white text-[10px]">✓</span>}
              </div>
              <span className={`text-xs font-bold leading-tight ${task.completed ? 'text-gray-400 line-through' : 'text-slate-700'}`}>
                {task.title}
              </span>
            </li>
          ))}
        </ul>
      </section>

      {/* Feedback / Chat Card */}
      <section className="flex-1 min-h-0 bg-white/90 backdrop-blur-xl rounded-3xl p-5 border border-pink-100 shadow-xl pointer-events-auto flex flex-col overflow-hidden">
        <h3 className="text-pink-800 font-black text-sm uppercase tracking-wider mb-3 flex items-center gap-2">
          <span className="text-lg">💬</span> 市民之声
        </h3>

        <div className="flex-1 overflow-y-auto space-y-3 pr-1 mb-3 scrollbar-hide">
          {feedbacks.map(f => (
            <div key={f.id} className="flex gap-2.5 animate-in slide-in-from-bottom-2 duration-300">
              <img src={f.avatar} alt="avatar" className="w-7 h-7 rounded-full border border-white shadow-sm flex-shrink-0" />
              <div className="flex-1">
                <div className="flex justify-between items-center mb-1">
                  <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wide">{f.author}</span>
                  <span className="text-[8px] text-slate-300">{f.time}</span>
                </div>
                <div className="bg-pink-50 p-2.5 rounded-2xl rounded-tl-none text-xs text-slate-700 leading-relaxed border border-pink-100/50 shadow-sm">
                  {f.text}
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-auto flex gap-2 pt-2 border-t border-gray-100">
          <input 
            type="text" 
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="输入回复..." 
            className="flex-1 text-xs bg-gray-50 border border-gray-200 rounded-full px-4 py-2 outline-none focus:bg-white focus:ring-2 focus:ring-pink-300 transition-all" 
          />
          <button 
            onClick={handleSend}
            className="bg-pink-500 hover:bg-pink-600 text-white w-8 h-8 flex items-center justify-center rounded-full shadow-lg shadow-pink-200 transition-transform active:scale-90"
          >
            <span className="text-xs mb-0.5 ml-0.5">➤</span>
          </button>
        </div>
      </section>

    </div>
  );
};
